import * as React from "react"
import { Slot } from "@radix-ui/react-slot"

import { cn } from "@/lib/utils"

/** Numbers with a dot beneath each; the current page's dot is the accent. */
function Pagination({ className, ...props }: React.ComponentProps<"nav">) {
  return <nav data-slot="pagination" aria-label="Pages" className={className} {...props} />
}

function PaginationContent({ className, ...props }: React.ComponentProps<"ul">) {
  return <ul data-slot="pagination-content" className={cn("db-pager", className)} {...props} />
}

function PaginationItem(props: React.ComponentProps<"li">) {
  return <li data-slot="pagination-item" {...props} />
}

type PaginationLinkProps = React.ComponentProps<"a"> & {
  isActive?: boolean
  /** Render your own link (Next's Link, say) with the pager's look. */
  asChild?: boolean
}

/** A page number. Give it an aria-label ("Page 3"); the number alone is a poor name. */
function PaginationLink({ isActive = false, asChild = false, ...props }: PaginationLinkProps) {
  const Comp = asChild ? Slot : "a"
  return <Comp data-slot="pagination-link" aria-current={isActive ? "page" : undefined} {...props} />
}

type StepProps = Omit<PaginationLinkProps, "isActive" | "href"> & {
  /** Omit at the first or last page: the step shows, but doesn't go anywhere. */
  href?: string
}

function step(kind: "previous" | "next", dflt: string) {
  return function Step({ href, asChild = false, className, children = dflt, ...props }: StepProps) {
    const Comp = asChild ? Slot : href === undefined ? "span" : "a"
    // A word label (the neighbour's name) needs its direction spoken too.
    const label = typeof children === "string" && children !== dflt ? `${kind === "previous" ? "Previous" : "Next"}: ${children}` : undefined
    return (
      <Comp
        data-slot={`pagination-${kind}`}
        className={cn("db-pager-step", className)}
        rel={href === undefined ? undefined : kind === "previous" ? "prev" : "next"}
        aria-label={label}
        aria-disabled={href === undefined && !asChild ? true : undefined}
        {...(href === undefined ? {} : { href })}
        {...props}
      >
        {children}
      </Comp>
    )
  }
}

/** ← Previous, or ← and a word: the neighbour's name reads well here. The arrow is drawn, so pass only the words. */
const PaginationPrevious = step("previous", "Previous")
/** Next →, or a word and →. */
const PaginationNext = step("next", "Next")

/** Pages left out. */
function PaginationEllipsis({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span data-slot="pagination-ellipsis" className={cn("db-pager-gap", className)} {...props}>
      <span aria-hidden="true">…</span>
      <span className="db-sr">More pages</span>
    </span>
  )
}

export { Pagination, PaginationContent, PaginationItem, PaginationLink, PaginationPrevious, PaginationNext, PaginationEllipsis, type PaginationLinkProps }

@layer components {
  /* ── db-pager ── numbers; a dot under each, the current one in accent.
     The list is the pager; Previous and Next are words with a drawn arrow and no dot. */
  .db-pager { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--db-space-5); font-size: var(--db-mp); line-height: var(--db-mp-lh); font-variant-numeric: tabular-nums; }
  .db-pager a[data-slot="pagination-link"] {
    position: relative; display: inline-block; padding: 0 0 var(--db-space-3); color: var(--db-pencil); text-decoration: none; cursor: pointer;
    font-weight: 200; transition: color var(--db-allegro), font-weight var(--db-moderato) var(--db-breath);
  }
  .db-pager a[data-slot="pagination-link"]::after {
    content: ""; position: absolute; inset-inline-start: 50%; inset-block-end: 0; translate: -50% 0;
    width: 3px; height: 3px; border-radius: 50%; background: var(--db-rule-strong);
    transition: width var(--db-moderato) var(--db-spiccato), height var(--db-moderato) var(--db-spiccato), background-color var(--db-moderato), box-shadow var(--db-allegro);
  }
  :is([dir="rtl"], [dir="rtl"] *) .db-pager a[data-slot="pagination-link"]::after { translate: 50% 0; }
  .db-pager a[data-slot="pagination-link"]:is(:hover, [data-force~="hover"]) { color: var(--db-graphite); }
  .db-pager a[data-slot="pagination-link"]:is(:hover, [data-force~="hover"]):not([aria-current="page"])::after { width: 6px; height: 6px; background-color: transparent; box-shadow: inset 0 0 0 var(--db-hairline) var(--db-rule-strong); }
  /* Weight falls with distance from the current page: 600, then 350 beside it, then 200. */
  .db-pager > :is(li:has(> [aria-current="page"]) + li, li:has(+ li > [aria-current="page"])) > a[data-slot="pagination-link"] { font-weight: 350; color: var(--db-graphite); }
  .db-pager a[data-slot="pagination-link"][aria-current="page"] { color: var(--db-ink); font-weight: 600; }
  .db-pager a[data-slot="pagination-link"][aria-current="page"]::after { width: 6px; height: 6px; background: var(--db-accent); }

  .db-pager-step { display: inline-block; padding: 0 0 var(--db-space-3); color: var(--db-graphite); font-weight: 300; text-decoration: none; cursor: pointer; transition: color var(--db-allegro); }
  a.db-pager-step:is(:hover, [data-force~="hover"]) { color: var(--db-ink); }
  .db-pager-step[aria-disabled="true"] { color: var(--db-pencil); cursor: default; }
  [data-slot="pagination-previous"]::before { content: "← " / ""; }
  [data-slot="pagination-next"]::after { content: " →" / ""; }
  :is([dir="rtl"], [dir="rtl"] *) [data-slot="pagination-previous"]::before { content: "→ " / ""; }
  :is([dir="rtl"], [dir="rtl"] *) [data-slot="pagination-next"]::after { content: " ←" / ""; }
  .db-pager-gap { display: inline-block; padding: 0 0 var(--db-space-3); color: var(--db-pencil); font-weight: 200; }
}
